import random
from collections import deque

def girth_or_short(edges, n=22, max_girth=6):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = deque([start])
        min_cycle = float('inf')
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
                        if min_cycle <= max_girth:
                            return min_cycle
        return min_cycle

    girth = min((bfs(i) for i in range(n)), default=float('inf'))
    return girth

col = [0]*8 + [1]*7 + [2]*7
possible_edges = [(i,j) for i in range(22) for j in range(i+1,22) if col[i] != col[j]]

random.seed(42)
min_g = 100
counts = {3:0, 4:0, 5:0, 6:0, 7:0, 8:0}
for trial in range(5000):
    selected = random.sample(possible_edges, 27)
    g = girth_or_short(selected)
    if g in counts:
        counts[g] += 1
    if g < min_g:
        min_g = g

print('Counts of girth:', counts)
print('Smallest seen:', min_g)
